(4369705, 629087, 63267, '<td valign="top">Wow, this is busy with all of the different views of your fish.  The belnding had to have been a challenge.  I like your take on the challenge.  8.</td>', 'Wow, this is busy with all of the different views of your fish.  The belnding had to have been a challenge.  I like your take on the challenge.  8.', '2008-01-07 12:05:59.000000', NULL, 1),
(4369712, 628065, 63267, '<td valign="top">This image is too dark for me. There really isn''t much more I can say about it than that, and for that I am sorry.  But it is just too dark.  5.</td>', 'This image is too dark for me. There really isn''t much more I can say about it than that, and for that I am sorry.  But it is just too dark.  5.', '2008-01-07 12:07:39.000000', NULL, 1),
(4369722, 629945, 63267, '<td valign="top">That is pretty cool.  I bet the kite is tough to fly on really windy days!  It looks like the horizon is severely crooked.  Maybe just an illusion or a sloped beach, but it distracts my eyes from the kite.  6.</td>', 'That is pretty cool.  I bet the kite is tough to fly on really windy days!  It looks like the horizon is severely crooked.  Maybe just an illusion or a sloped beach, but it distracts my eyes from the kite.  6.', '2008-01-07 12:09:06.000000', NULL, 1),
(4369726, 629020, 63267, '<td valign="top">Great image here.  I like the processing.  I think you have a great concept, and composition is well done with a great leading lines. 7.</td>', 'Great image here.  I like the processing.  I think you have a great concept, and composition is well done with a great leading lines. 7.', '2008-01-07 12:10:04.000000', NULL, 1),
(4369735, 629883, 63267, '<td valign="top">I like it.  Looks like it was a fun shoot.  I like the balck and white.  Only thing I don''t like it is looks soft to me.  The frame at the rear could have been omitted.  You have some serious potential on this shot, I think the aperture just need to be opened up a bit more to get mor ein focus.<br/> <br/>6.</td>', 'I like it.  Looks like it was a fun shoot.  I like the balck and white.  Only thing I don''t like it is looks soft to me.  The frame at the rear could have been omitted.  You have some serious potential on this shot, I think the aperture just need to be opened up a bit more to get mor ein focus. 6.', '2008-01-07 12:11:34.000000', NULL, 1),
(4369741, 629441, 63267, '<td valign="top">Great sequence here. I like the spacing as so many of these shots have people jumbled up.  But you have done well here.  The skier does look a bit soft or OOF though.  6.</td>', 'Great sequence here. I like the spacing as so many of these shots have people jumbled up.  But you have done well here.  The skier does look a bit soft or OOF though.  6.', '2008-01-07 12:12:44.000000', NULL, 1),
(4369750, 629705, 63267, '<td valign="top">Now this is just wonderful. I bet this will be framed and hanging on the wall.  I think of images like this as challenge success.  So many people griped about the new rules, and yet without them people wouldn''t put together such wonderful shots as this.<br/> <br/>I can''t think of anything that this image doens''t have going for it.  A 10 is an understatement!</td>', 'Now this is just wonderful. I bet this will be framed and hanging on the wall.  I think of images like this as challenge success.  So many people griped about the new rules, and yet without them people wouldn''t put together such wonderful shots as this. I can''t think of anything that this image doens''t have going for it.  A 10 is an understatement!', '2008-01-07 12:14:07.000000', NULL, 1),
(4369761, 629850, 63267, '<td valign="top">Niely done.  It looks hard to blend all of those hands without making them floating in space due to a lack of an attaching forearm.  You did well and have a great shot!  8</td>', 'Niely done.  It looks hard to blend all of those hands without making them floating in space due to a lack of an attaching forearm.  You did well and have a great shot!  8', '2008-01-07 12:15:00.000000', NULL, 1),
(4369776, 629725, 63267, '<td valign="top">Great take on the challenge.  I really like this one.  It is so different than all of the jumping and action shots.  The action is subtle and it is nice.  Well done! 9</td>', 'Great take on the challenge.  I really like this one.  It is so different than all of the jumping and action shots.  The action is subtle and it is nice.  Well done! 9', '2008-01-07 12:16:33.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4369781, 629878, 63267, '<td valign="top">I don''t care for the border.  If it had surrounded the whole image that would be great, but the lack of border on the sides ruins it for me.<br/> <br/>Overall a nice shot, but the vignetting takes away from the image.  Good action, and good spacing on the rider, jsut hampered by the border and the vignetting.  6.</td>', 'I don''t care for the border.  If it had surrounded the whole image that would be great, but the lack of border on the sides ruins it for me. Overall a nice shot, but the vignetting takes away from the image.  Good action, and good spacing on the rider, jsut hampered by the border and the vignetting.  6.', '2008-01-07 12:17:56.000000', NULL, 1),
(4369790, 629131, 63267, '<td valign="top">What a spectacular shot.  Only quip I have is the horizon.  Why is it crooked?  Still the clouds, the action, the lighting is all magical.  I can''t let the horizon ruin this wonderful image for me so still a 7.</td>', 'What a spectacular shot.  Only quip I have is the horizon.  Why is it crooked?  Still the clouds, the action, the lighting is all magical.  I can''t let the horizon ruin this wonderful image for me so still a 7.', '2008-01-07 12:19:09.000000', NULL, 1),
