(4372384, 629825, 61818, '<td valign="top">Nice capture.  Maybe center the ''guys'' so there is equal space in front and behind?  Overall a nice entry.</td>', 'Nice capture.  Maybe center the ''guys'' so there is equal space in front and behind?  Overall a nice entry.', '2008-01-07 23:37:02.000000', NULL, 1),
(4372386, 629441, 50695, '<td valign="top">scalvert: nope. looks like multiple skiers.<br/> <br/>muckpond: looks like the same skier to me.<br/> <br/>ursula: maybe they''re all just wearing the same thing.<br/> <br/>scalvert: the odds against that are huge.<br/> <br/>ursula: maybe they called each other.<br/> <br/>scalvert: ugh. guys don''t do that.<br/> <br/>muckpond: either way, it''s not natural!</td>', 'scalvert: nope. looks like multiple skiers. muckpond: looks like the same skier to me. ursula: maybe they''re all just wearing the same thing. scalvert: the odds against that are huge. ursula: maybe they called each other. scalvert: ugh. guys don''t do that. muckpond: either way, it''s not natural!', '2008-01-07 23:37:37.000000', NULL, 1),
(4372387, 629712, 61818, '<td valign="top">Looks like you had a nice idea here that didn''t translate so well in the execution.</td>', 'Looks like you had a nice idea here that didn''t translate so well in the execution.', '2008-01-07 23:37:44.000000', NULL, 1),
(4372388, 629825, 41802, '<td valign="top">I really like the photo.  The snow falling is prefect.  The only thing I would do is cropped the left side a little more.</td>', 'I really like the photo.  The snow falling is prefect.  The only thing I would do is cropped the left side a little more.', '2008-01-07 23:37:47.000000', NULL, 1),
(4372391, 629448, 41802, '<td valign="top">Well it took me a minute to get it but it is very clever. I would be really curious to see how you score.  I hope the best for you.</td>', 'Well it took me a minute to get it but it is very clever. I would be really curious to see how you score.  I hope the best for you.', '2008-01-07 23:38:36.000000', NULL, 1),
(4372394, 629961, 52336, '<td valign="top">Mysterious and beautiful.  This seems to be snowfall... whatever it is, it is absolutely stunning, and a gorgeous effect.</td>', 'Mysterious and beautiful.  This seems to be snowfall... whatever it is, it is absolutely stunning, and a gorgeous effect.', '2008-01-07 23:39:03.000000', NULL, 1),
(4372395, 629725, 41802, '<td valign="top">Nice use of time lapse.  I like the background it really enhances the subject.</td>', 'Nice use of time lapse.  I like the background it really enhances the subject.', '2008-01-07 23:39:13.000000', NULL, 1),
(4372396, 629226, 61818, '<td valign="top">I don''t normally pay much attention to birds walking down the beach.  A scene like this might catch my eye though.  Maybe.</td>', 'I don''t normally pay much attention to birds walking down the beach.  A scene like this might catch my eye though.  Maybe.', '2008-01-07 23:39:14.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4372398, 629501, 36006, '<td valign="top">Nice photo, but this seems to be a shoehorn image, DNMC.</td>', 'Nice photo, but this seems to be a shoehorn image, DNMC.', '2008-01-07 23:39:21.000000', NULL, 1),
(4372399, 628481, 50695, '<td valign="top">GeneralE: that''s not a single motion. that horse is all over the place.<br/> <br/>muckpond: of course not! what do you think they get paid for?<br/> <br/>GeneralE: horses do not work for money.<br/> <br/>muckpond: What? What?<br/> <br/>sher: what''s wrong, muckie?<br/> <br/>muckpond: They Pay Horses, Don''t They?</td>', 'GeneralE: that''s not a single motion. that horse is all over the place. muckpond: of course not! what do you think they get paid for? GeneralE: horses do not work for money. muckpond: What? What? sher: what''s wrong, muckie? muckpond: They Pay Horses, Don''t They?', '2008-01-07 23:39:31.000000', NULL, 1),
(4372401, 628481, 41802, '<td valign="top">Woo-hoo!  Cool piece.  Great use of the vibrant colors to bring us into the piece.</td>', 'Woo-hoo!  Cool piece.  Great use of the vibrant colors to bring us into the piece.', '2008-01-07 23:39:56.000000', NULL, 1),
(4372403, 629756, 61818, '<td valign="top">A few of these type of shots in the challenge and I think they work well.  IF this were a bit wider in scope, so that the transition was more gradual it would work better for me.</td>', 'A few of these type of shots in the challenge and I think they work well.  IF this were a bit wider in scope, so that the transition was more gradual it would work better for me.', '2008-01-07 23:40:14.000000', NULL, 1),
(4372404, 628555, 41802, '<td valign="top">I like the contrast between the biker and the graffiti.  Cool job.</td>', 'I like the contrast between the biker and the graffiti.  Cool job.', '2008-01-07 23:40:35.000000', NULL, 1),
(4372408, 627641, 61818, '<td valign="top">This has more of an ''art'' feel to it and less of a soulless, ''I''m just using the technique'' feel that so many other entries suffer from.</td>', 'This has more of an ''art'' feel to it and less of a soulless, ''I''m just using the technique'' feel that so many other entries suffer from.', '2008-01-07 23:41:10.000000', NULL, 1),
(4372411, 629562, 61818, '<td valign="top">If there''s one thing this challenge has taught me, it is that if you crowd ten copies of one person next to each other it doesn''t look like one person doing something - it looks like a crowd standing there.  You''ve got the nice colors and everything here, but spacing this guy out would really add to the sense of vastness and serenity.  All jammed up like this, his presence adds an unwelcome sense of business to that area of the image.</td>', 'If there''s one thing this challenge has taught me, it is that if you crowd ten copies of one person next to each other it doesn''t look like one person doing something - it looks like a crowd standing there.  You''ve got the nice colors and everything here, but spacing this guy out would really add to the sense of vastness and serenity.  All jammed up like this, his presence adds an unwelcome sense of business to that area of the image.', '2008-01-07 23:42:36.000000', NULL, 1),
(4372412, 629725, 52336, '<td valign="top">Pretty and engaging.</td>', 'Pretty and engaging.', '2008-01-07 23:42:47.000000', NULL, 1),
(4372413, 629754, 41802, '<td valign="top">I had to give you a bonus point for the dogs expression in the middle! It is priceless!</td>', 'I had to give you a bonus point for the dogs expression in the middle! It is priceless!', '2008-01-07 23:43:02.000000', NULL, 1),
(4372414, 629687, 61818, '<td valign="top">I admire the attempt at humor.</td>', 'I admire the attempt at humor.', '2008-01-07 23:43:21.000000', NULL, 1),
(4372419, 629851, 41802, '<td valign="top">Very nice use of editing to really enhance the ball and hoop.  Great composition.</td>', 'Very nice use of editing to really enhance the ball and hoop.  Great composition.', '2008-01-07 23:44:08.000000', NULL, 1),
(4372423, 629961, 36006, '<td valign="top">Interesting photo, but because this is time lapse, and I can''t say that it is, or not, it prolly won''t do well. Just my opinion.<br/> <br/>Other than that, I like it.</td>', 'Interesting photo, but because this is time lapse, and I can''t say that it is, or not, it prolly won''t do well. Just my opinion. Other than that, I like it.', '2008-01-07 23:45:06.000000', NULL, 1),
(4372424, 628806, 41802, '<td valign="top">Great capture.  I love what you were able to do with the sun and lighting.</td>', 'Great capture.  I love what you were able to do with the sun and lighting.', '2008-01-07 23:45:09.000000', NULL, 1),
(4372425, 629961, 61818, '<td valign="top">I haven''t sunk to whatever level this is appealing on.  I admire you for submitting it though, and it will be interesting to see how it fares.</td>', 'I haven''t sunk to whatever level this is appealing on.  I admire you for submitting it though, and it will be interesting to see how it fares.', '2008-01-07 23:45:31.000000', NULL, 1),
(4372433, 629942, 41802, '<td valign="top">Cool shot, I like the expression captured on her face.  I would be cursious to see the shot with the top cropped off.</td>', 'Cool shot, I like the expression captured on her face.  I would be cursious to see the shot with the top cropped off.', '2008-01-07 23:46:48.000000', NULL, 1),
(4372437, 629223, 41802, '<td valign="top">I really like the shot.  Good use of the natural setting.</td>', 'I really like the shot.  Good use of the natural setting.', '2008-01-07 23:47:47.000000', NULL, 1),
(4372442, 629938, 41802, '<td valign="top">Awesome idea.  I can''t wait to see after the challenge if these were all his hands.  Good choice of black and white to focus on the subject.</td>', 'Awesome idea.  I can''t wait to see after the challenge if these were all his hands.  Good choice of black and white to focus on the subject.', '2008-01-07 23:48:31.000000', NULL, 1),
(4372444, 629945, 41802, '<td valign="top">Cool idea.  I like the idea,  good use of negative space.</td>', 'Cool idea.  I like the idea,  good use of negative space.', '2008-01-07 23:49:03.000000', NULL, 1),
(4372445, 629486, 41802, '<td valign="top">I like the idea, I would like to see a little more contrast to draw out the colors.</td>', 'I like the idea, I would like to see a little more contrast to draw out the colors.', '2008-01-07 23:49:27.000000', NULL, 1),
(4372448, 629284, 41802, '<td valign="top">I love that he comes out of the border.  You did an awesome capturing this one.</td>', 'I love that he comes out of the border.  You did an awesome capturing this one.', '2008-01-07 23:50:02.000000', NULL, 1),
(4372454, 629523, 41802, '<td valign="top">Wow that is quite a kick.  I wish he landed facing the camera.</td>', 'Wow that is quite a kick.  I wish he landed facing the camera.', '2008-01-07 23:50:41.000000', NULL, 1),
(4372455, 628714, 41802, '<td valign="top">Cool shot.  I love that you were able to capture this while he/she was talking!</td>', 'Cool shot.  I love that you were able to capture this while he/she was talking!', '2008-01-07 23:51:09.000000', NULL, 1),
