(4372458, 629546, 41802, '<td valign="top">Wow this is really beautiful! Excellent job on the coloring.</td>', 'Wow this is really beautiful! Excellent job on the coloring.', '2008-01-07 23:51:57.000000', NULL, 1),
(4372460, 627954, 41802, '<td valign="top">I really like the action.  Since we see her on the edge I would like her to make it all the way across.  Nice work.</td>', 'I really like the action.  Since we see her on the edge I would like her to make it all the way across.  Nice work.', '2008-01-07 23:52:56.000000', NULL, 1),
(4372464, 628985, 41802, '<td valign="top">Cool shot, the coloring is very vibrant.  I like that you started looking right at the camera.</td>', 'Cool shot, the coloring is very vibrant.  I like that you started looking right at the camera.', '2008-01-07 23:53:36.000000', NULL, 1),
(4372467, 629952, 41802, '<td valign="top">Wow this is cool.  I love it! I will be curious to see how you were able to capture something this cool.</td>', 'Wow this is cool.  I love it! I will be curious to see how you were able to capture something this cool.', '2008-01-07 23:54:13.000000', NULL, 1),
(4372472, 628021, 41802, '<td valign="top">Oh I love paper airplanes.  This is really awesome.  The setting is wonderful.</td>', 'Oh I love paper airplanes.  This is really awesome.  The setting is wonderful.', '2008-01-07 23:55:44.000000', NULL, 1),
(4372476, 629863, 41802, '<td valign="top">Awesome landing.  I like what you were able to capture.  Great focus!</td>', 'Awesome landing.  I like what you were able to capture.  Great focus!', '2008-01-07 23:56:16.000000', NULL, 1),
(4372480, 629708, 41802, '<td valign="top">Wow I love this.  You were really original! I hope you do really well.</td>', 'Wow I love this.  You were really original! I hope you do really well.', '2008-01-07 23:56:55.000000', NULL, 1),
(4372483, 629944, 41802, '<td valign="top">Cool idea.  I really like this idea.  I wish the bottom corner weren''t lit, it really draws me into the smudges.</td>', 'Cool idea.  I really like this idea.  I wish the bottom corner weren''t lit, it really draws me into the smudges.', '2008-01-07 23:57:55.000000', NULL, 1),
(4372485, 629741, 41802, '<td valign="top">Cool shot.  I wish we had a little close view of the boat but I like the include of the water.</td>', 'Cool shot.  I wish we had a little close view of the boat but I like the include of the water.', '2008-01-07 23:58:26.000000', NULL, 1),
