(4377431, 629878, 57229, '<td valign="top">Either/or - Crop to half of the first bike or crop the other way down to four. Maybe :-) Good action sequence.</td>', 'Either/or - Crop to half of the first bike or crop the other way down to four. Maybe :-) Good action sequence.', '2008-01-09 11:26:23.000000', NULL, 1),
(4377435, 629754, 57229, '<td valign="top">Unusual choice of moving subject and situation. The colours make it hard for you. Fun shot.</td>', 'Unusual choice of moving subject and situation. The colours make it hard for you. Fun shot.', '2008-01-09 11:27:27.000000', NULL, 1),
(4377438, 629131, 61222, '<td valign="top">Cool image my favorite so far :-). How lucky to have a rainbow.</td>', 'Cool image my favorite so far :-). How lucky to have a rainbow.', '2008-01-09 11:28:14.000000', NULL, 1),
(4377442, 629946, 57229, '<td valign="top">Old enough to know better? Nicely done.</td>', 'Old enough to know better? Nicely done.', '2008-01-09 11:29:16.000000', NULL, 1),
(4377447, 628481, 61222, '<td valign="top">Wow great job on this one!!</td>', 'Wow great job on this one!!', '2008-01-09 11:31:19.000000', NULL, 1),
(4377465, 629020, 16461, '<td valign="top">very cool</td>', 'very cool', '2008-01-09 11:37:36.000000', NULL, 1),
(4377480, 629948, 57229, '<td valign="top">Something synthetic about the sky colour, but quite an excellent capture and composition.</td>', 'Something synthetic about the sky colour, but quite an excellent capture and composition.', '2008-01-09 11:42:17.000000', NULL, 1),
(4377486, 629962, 57229, '<td valign="top">This challenge was crying out for fireworks, so you deserve points for being quick off the mark and doing it.</td>', 'This challenge was crying out for fireworks, so you deserve points for being quick off the mark and doing it.', '2008-01-09 11:43:25.000000', NULL, 1),
(4377494, 629494, 57229, '<td valign="top">More of a metaphorical representation than a literal one. Not sure what I mean by that, but I can''t see someone standing by with a camera while a flower droops :-) I do like the concept, but I''m a bit less than thrilled by the result.</td>', 'More of a metaphorical representation than a literal one. Not sure what I mean by that, but I can''t see someone standing by with a camera while a flower droops :-) I do like the concept, but I''m a bit less than thrilled by the result.', '2008-01-09 11:45:47.000000', NULL, 1),
(4377496, 629295, 57229, '<td valign="top">Caterpillar cats!</td>', 'Caterpillar cats!', '2008-01-09 11:46:09.000000', NULL, 1),
(4377498, 628555, 57229, '<td valign="top">Nice catch.</td>', 'Nice catch.', '2008-01-09 11:46:22.000000', NULL, 1),
(4377504, 629557, 57229, '<td valign="top">Nice piece of work - you and him. I think the HDR colouring works OK on this - it''s an all round success :-)</td>', 'Nice piece of work - you and him. I think the HDR colouring works OK on this - it''s an all round success :-)', '2008-01-09 11:48:15.000000', NULL, 1),
(4377509, 629708, 57229, '<td valign="top">Nice one - not much to say when the thing''s so self-evident, but I think you got the steps about right, so bravo!</td>', 'Nice one - not much to say when the thing''s so self-evident, but I think you got the steps about right, so bravo!', '2008-01-09 11:49:30.000000', NULL, 1),
(4377517, 628806, 57229, '<td valign="top">So many great shots in this challenge. Silhouette and contre-jour gives you the shutter speed to stop motion. Clever as well as pretty.</td>', 'So many great shots in this challenge. Silhouette and contre-jour gives you the shutter speed to stop motion. Clever as well as pretty.', '2008-01-09 11:51:01.000000', NULL, 1),
(4377522, 629562, 57229, '<td valign="top">Succeeds but doesn''t inspire. Maybe I should be more excited about orange? Did the trick anyway.</td>', 'Succeeds but doesn''t inspire. Maybe I should be more excited about orange? Did the trick anyway.', '2008-01-09 11:52:19.000000', NULL, 1),
(4377527, 629712, 57229, '<td valign="top">Not sure if the blur/not blur has worked as well as it might, here. Good idea, though.</td>', 'Not sure if the blur/not blur has worked as well as it might, here. Good idea, though.', '2008-01-09 11:53:18.000000', NULL, 1),
(4377532, 629287, 57229, '<td valign="top">Bravo! Now get several over-trained over-paid lunkheads to jump on him :-) Very nice comp and colours.</td>', 'Bravo! Now get several over-trained over-paid lunkheads to jump on him :-) Very nice comp and colours.', '2008-01-09 11:55:41.000000', NULL, 1),
(4377539, 629706, 57229, '<td valign="top">Technically all there, but maybe there''s too many copies? It gets to look more like a queue than a motion sequence :-)</td>', 'Technically all there, but maybe there''s too many copies? It gets to look more like a queue than a motion sequence :-)', '2008-01-09 11:56:54.000000', NULL, 1),
(4377543, 629131, 57229, '<td valign="top">This is so beautiful. Is there some HDR in there making the sand glow? Front cover of the kind of science fiction book I lived on as a boy.</td>', 'This is so beautiful. Is there some HDR in there making the sand glow? Front cover of the kind of science fiction book I lived on as a boy.', '2008-01-09 11:58:10.000000', NULL, 1),
(4377544, 629941, 57229, '<td valign="top">This is what I wanted to do. Go bugs!</td>', 'This is what I wanted to do. Go bugs!', '2008-01-09 11:58:44.000000', NULL, 1),
(4377549, 629441, 57229, '<td valign="top">I hate skiers. He must be proud of this elegant little sequence though. Nicely done.</td>', 'I hate skiers. He must be proud of this elegant little sequence though. Nicely done.', '2008-01-09 12:00:36.000000', NULL, 1),
(4377551, 629686, 57229, '<td valign="top">Over saturated but pleasant - in my opinion that could do with being more humble and is usually wrong.</td>', 'Over saturated but pleasant - in my opinion that could do with being more humble and is usually wrong.', '2008-01-09 12:02:07.000000', NULL, 1),
(4377559, 629020, 57229, '<td valign="top">So they hatch out in the fields before finding their way to the malls and alleyways? Well documented.</td>', 'So they hatch out in the fields before finding their way to the malls and alleyways? Well documented.', '2008-01-09 12:04:07.000000', NULL, 1),
(4377565, 629322, 57229, '<td valign="top">He should take something for that seriousness. Drugs, maybe. Cute kid and neat sequence.</td>', 'He should take something for that seriousness. Drugs, maybe. Cute kid and neat sequence.', '2008-01-09 12:05:41.000000', NULL, 1),
(4377580, 629406, 57229, '<td valign="top">Some mothers do ''ave ''em. I presume you will be expounding on the calculus and laws of motion in your how-to tutorial.</td>', 'Some mothers do ''ave ''em. I presume you will be expounding on the calculus and laws of motion in your how-to tutorial.', '2008-01-09 12:09:54.000000', NULL, 1),
(4377587, 629694, 57229, '<td valign="top">Round and a round and a round we go. Tell him he''ll have to buy his own equipment if he doesn''t start looking a bit more excited about it. :-)</td>', 'Round and a round and a round we go. Tell him he''ll have to buy his own equipment if he doesn''t start looking a bit more excited about it. :-)', '2008-01-09 12:11:53.000000', NULL, 1),
(4377606, 629087, 57229, '<td valign="top">Bit of an art work, really. You''ve had to choose all sorts of opacities and overlaps. I keep thinking (only while looking at the picture, mind - it hasn''t got to me that bad), that if there was something to which this could be applied it could be a seriously powerful image.</td>', 'Bit of an art work, really. You''ve had to choose all sorts of opacities and overlaps. I keep thinking (only while looking at the picture, mind - it hasn''t got to me that bad), that if there was something to which this could be applied it could be a seriously powerful image.', '2008-01-09 12:15:21.000000', NULL, 1),
(4377617, 629961, 57229, '<td valign="top">What it is? What it is? Aarggh! Lovely picture.</td>', 'What it is? What it is? Aarggh! Lovely picture.', '2008-01-09 12:16:18.000000', NULL, 1),
(4377629, 629284, 57229, '<td valign="top">There''s no stopping him, jumped out of the frame. Boring old farts like me see only a real cool time and money waster, but it''s a great sequence capture and you got the snow right too :-)</td>', 'There''s no stopping him, jumped out of the frame. Boring old farts like me see only a real cool time and money waster, but it''s a great sequence capture and you got the snow right too :-)', '2008-01-09 12:18:14.000000', NULL, 1),
(4377642, 629523, 57229, '<td valign="top">All that without his glasses falling off? There is a great future for this boy.</td>', 'All that without his glasses falling off? There is a great future for this boy.', '2008-01-09 12:19:12.000000', NULL, 1),
(4377654, 628788, 57229, '<td valign="top">Have you made this so seamless that we (sorry, I) miss the point? Might be better in a more huge format. Lots of nice, anyway.</td>', 'Have you made this so seamless that we (sorry, I) miss the point? Might be better in a more huge format. Lots of nice, anyway.', '2008-01-09 12:21:08.000000', NULL, 1),
(4377662, 629823, 57229, '<td valign="top">Have you added HDR? Something makes the umbrella''s corny colours right. Good picture.</td>', 'Have you added HDR? Something makes the umbrella''s corny colours right. Good picture.', '2008-01-09 12:22:27.000000', NULL, 1),
(4377668, 629756, 57229, '<td valign="top">How d''you do all this seamlessness? Or is that a bit of noise reduction booboo in the trees toward the left side? Good idea well done.</td>', 'How d''you do all this seamlessness? Or is that a bit of noise reduction booboo in the trees toward the left side? Good idea well done.', '2008-01-09 12:24:31.000000', NULL, 1),
(4377673, 629186, 57229, '<td valign="top">The K.I.S.S. principle makes this a front runner. (OK, that and the one about cream floating to the top).</td>', 'The K.I.S.S. principle makes this a front runner. (OK, that and the one about cream floating to the top).', '2008-01-09 12:25:34.000000', NULL, 1),
(4377680, 629600, 57229, '<td valign="top">Lerv - lerv - lerv - ching ching tee ching. Sorry, it set me off. Lovely.</td>', 'Lerv - lerv - lerv - ching ching tee ching. Sorry, it set me off. Lovely.', '2008-01-09 12:26:45.000000', NULL, 1),
(4377688, 629467, 57229, '<td valign="top">These things are familiar to your regular viewers? Something tells me it must be good, but nothing much tells me why. I like the title.</td>', 'These things are familiar to your regular viewers? Something tells me it must be good, but nothing much tells me why. I like the title.', '2008-01-09 12:28:22.000000', NULL, 1),
(4377694, 628714, 32033, '<td valign="top">wood carvings?</td>', 'wood carvings?', '2008-01-09 12:29:34.000000', NULL, 1),
(4377697, 629583, 57229, '<td valign="top">Neon green that looks more poisonous than organic. I''m guessing over saturated. I think you''ve done the masking and erasing well, but it wasn''t easy.</td>', 'Neon green that looks more poisonous than organic. I''m guessing over saturated. I think you''ve done the masking and erasing well, but it wasn''t easy.', '2008-01-09 12:30:19.000000', NULL, 1),
(4377713, 629710, 57229, '<td valign="top">Whither and why and what? I suppose you don''t <u>have</u> to use up all of the new rule opportunities. You can photograph an idea instead. Brave.</td>', 'Whither and why and what? I suppose you don''t have to use up all of the new rule opportunities. You can photograph an idea instead. Brave.', '2008-01-09 12:32:56.000000', NULL, 1),
(4377724, 629705, 88784, '<td valign="top">I love this one!</td>', 'I love this one!', '2008-01-09 12:35:53.000000', NULL, 1),
(4377836, 629131, 72070, '<td valign="top">great shot, with lots of emotoions!</td>', 'great shot, with lots of emotoions!', '2008-01-09 13:07:36.000000', NULL, 1),
(4377842, 629823, 72070, '<td valign="top">i lovve the colours an tones here! well done!</td>', 'i lovve the colours an tones here! well done!', '2008-01-09 13:09:28.000000', NULL, 1),
(4377996, 629523, 80859, '<td valign="top">he''s got some height and great form on that kick!  great job catching it, too!  my personal taste would be that there were some colour in the sky but great job, overall :)</td>', 'he''s got some height and great form on that kick!  great job catching it, too!  my personal taste would be that there were some colour in the sky but great job, overall :)', '2008-01-09 13:57:43.000000', NULL, 1),
(4378012, 627641, 80859, '<td valign="top">good example of time lapse.  the model seems a little out of focus and running across a flat surface isn''t the most exciting.  the wall is very interesting and the colours are nice against that background.</td>', 'good example of time lapse.  the model seems a little out of focus and running across a flat surface isn''t the most exciting.  the wall is very interesting and the colours are nice against that background.', '2008-01-09 14:03:00.000000', NULL, 1),
(4378023, 629757, 80859, '<td valign="top">great shot.  i love the signs on the left and the perspective, though the light pole is a bit distracting.  the time lapse part came out really well, too.</td>', 'great shot.  i love the signs on the left and the perspective, though the light pole is a bit distracting.  the time lapse part came out really well, too.', '2008-01-09 14:07:11.000000', NULL, 1),
(4378070, 629318, 80859, '<td valign="top">nice colour.  splash is really cool.  a perfect little wall.  for the time lapse, though, it''s a little difficult to say that''s all the same drop in different phases of falling. i know it is because of the nature of the challenge, but if i didn''t know, i probably wouldn''t think it was time lapse.</td>', 'nice colour.  splash is really cool.  a perfect little wall.  for the time lapse, though, it''s a little difficult to say that''s all the same drop in different phases of falling. i know it is because of the nature of the challenge, but if i didn''t know, i probably wouldn''t think it was time lapse.', '2008-01-09 14:23:29.000000', NULL, 1),
(4378076, 629948, 80859, '<td valign="top">neat photo.  i want to see his feet hit earth!  i guess it would have been hard to predict just where exact landing point would be.  you did a great job getting that.  i like the painted sky and the low-flying clouds in the background.</td>', 'neat photo.  i want to see his feet hit earth!  i guess it would have been hard to predict just where exact landing point would be.  you did a great job getting that.  i like the painted sky and the low-flying clouds in the background.', '2008-01-09 14:26:18.000000', NULL, 1),
(4378080, 627954, 80859, '<td valign="top">nice shot.  very colourful. i think it would have benefitted one more image of her reaching the other side to complete the set.</td>', 'nice shot.  very colourful. i think it would have benefitted one more image of her reaching the other side to complete the set.', '2008-01-09 14:28:09.000000', NULL, 1),
(4378095, 629467, 80859, '<td valign="top">i''m not sure what kind of ''apparatus'' that is, but the focus is nice and sharp and it looks pretty cool.  i think it may have benefitted from one more image.. maybe just as it entered the left side.<br/> <br/>ok..i looked it up...neat toy.</td>', 'i''m not sure what kind of ''apparatus'' that is, but the focus is nice and sharp and it looks pretty cool.  i think it may have benefitted from one more image.. maybe just as it entered the left side. ok..i looked it up...neat toy.', '2008-01-09 14:35:25.000000', NULL, 1),
(4378104, 629553, 80859, '<td valign="top">i can definitely tell it''s time lapse.  great shot.  i wonder about the fact that the bottom half of the body and head doesn''t show any position change over time like the arms and club, which seems a little bit awkward.  i love the perspective of the club as it reaches the front and you can see how wide it is.</td>', 'i can definitely tell it''s time lapse.  great shot.  i wonder about the fact that the bottom half of the body and head doesn''t show any position change over time like the arms and club, which seems a little bit awkward.  i love the perspective of the club as it reaches the front and you can see how wide it is.', '2008-01-09 14:39:37.000000', NULL, 1),
(4378109, 629878, 80859, '<td valign="top">nice idea following the bike through its jump.  the photo seems a litle dark, but overall good shot :)</td>', 'nice idea following the bike through its jump.  the photo seems a litle dark, but overall good shot :)', '2008-01-09 14:41:31.000000', NULL, 1),
(4378141, 629751, 80859, '<td valign="top">this is unique in this challenge and beautifully shot. a little bit more DOF might be nice to get the center of the clock more in focus.  also, i would have liked to see it show a wider range of time change.</td>', 'this is unique in this challenge and beautifully shot. a little bit more DOF might be nice to get the center of the clock more in focus.  also, i would have liked to see it show a wider range of time change.', '2008-01-09 14:53:08.000000', NULL, 1),
(4378145, 628895, 80859, '<td valign="top">i like the movement.  the gun is almost invisible against the background, though.</td>', 'i like the movement.  the gun is almost invisible against the background, though.', '2008-01-09 14:54:35.000000', NULL, 1),
(4378150, 629908, 80859, '<td valign="top">nice b&amp;w photo.  very simple, but well-done.</td>', 'nice b&w photo.  very simple, but well-done.', '2008-01-09 14:55:41.000000', NULL, 1),
(4378178, 629087, 80859, '<td valign="top">cool photo.  i like it.  hard to peg it as time lapse but really neat.  nice sharp focus.</td>', 'cool photo.  i like it.  hard to peg it as time lapse but really neat.  nice sharp focus.', '2008-01-09 15:00:37.000000', NULL, 1),
(4378182, 629694, 80859, '<td valign="top">nice winter shot.  demonstrates time lapse well.</td>', 'nice winter shot.  demonstrates time lapse well.', '2008-01-09 15:02:11.000000', NULL, 1),
(4378256, 629226, 80859, '<td valign="top">the title implies that it''s more than one bird there, but i suspect it isn''t.  it''s a beautiful seaside photo, but it is not clear to anyone that didn''t know that it''s one bird''s path through time.</td>', 'the title implies that it''s more than one bird there, but i suspect it isn''t.  it''s a beautiful seaside photo, but it is not clear to anyone that didn''t know that it''s one bird''s path through time.', '2008-01-09 15:21:54.000000', NULL, 1),
(4378527, 629757, 43410, '<td valign="top">first image i''ve seen seen so far, and i know already that this one will, and should, blue<br/> <br/>early congratulations!  10</td>', 'first image i''ve seen seen so far, and i know already that this one will, and should, blue early congratulations!  10', '2008-01-09 16:35:37.000000', NULL, 1),
(4378539, 629705, 43410, '<td valign="top">that''s awesome!  drachoo?  just a guess, looks like your style, i could be wrong<br/> <br/>great job!</td>', 'that''s awesome!  drachoo?  just a guess, looks like your style, i could be wrong great job!', '2008-01-09 16:39:59.000000', NULL, 1),
(4378550, 629339, 43410, '<td valign="top">heh this is a really cool effect.  great job</td>', 'heh this is a really cool effect.  great job', '2008-01-09 16:43:51.000000', NULL, 1),
(4378557, 629961, 43410, '<td valign="top">very interesting shot</td>', 'very interesting shot', '2008-01-09 16:45:51.000000', NULL, 1),
(4378560, 629546, 43410, '<td valign="top">i LOVE it, very nice use of day to night time time lapse.  GREAT job. 10<br/> <br/>this is my pick for a ribbon</td>', 'i LOVE it, very nice use of day to night time time lapse.  GREAT job. 10 this is my pick for a ribbon', '2008-01-09 16:46:48.000000', NULL, 1),
(4378702, 629523, 62009, '<td valign="top">Perhaps catch the landing and put it in there as well.  The sky seems blown out to me and the grass looks rather brown.  Interesting take, though.</td>', 'Perhaps catch the landing and put it in there as well.  The sky seems blown out to me and the grass looks rather brown.  Interesting take, though.', '2008-01-09 17:42:42.000000', NULL, 1),
(4378705, 629751, 62009, '<td valign="top">I like this.  Interesting POV.  Personally, I would have caught the minute hand at 12 or 13 minutes after, as well.<br/> <br/>Great focus and concept.</td>', 'I like this.  Interesting POV.  Personally, I would have caught the minute hand at 12 or 13 minutes after, as well. Great focus and concept.', '2008-01-09 17:43:52.000000', NULL, 1),
(4378713, 629710, 62009, '<td valign="top">Very interesting.  The background isn''t continuous to me.  I can see the lines between the paper and the wall or whatever it is and it distracts me a bit.  Also, the desaturation looks odd to me.  I really like the concept, though.</td>', 'Very interesting.  The background isn''t continuous to me.  I can see the lines between the paper and the wall or whatever it is and it distracts me a bit.  Also, the desaturation looks odd to me.  I really like the concept, though.', '2008-01-09 17:46:25.000000', NULL, 1),
(4378715, 629739, 62009, '<td valign="top">Very nice motion capture.</td>', 'Very nice motion capture.', '2008-01-09 17:47:18.000000', NULL, 1),
(4378718, 629825, 62009, '<td valign="top">Fun and playfull shot.  It is quite noisy to me, but that could (probably is) just the snow.</td>', 'Fun and playfull shot.  It is quite noisy to me, but that could (probably is) just the snow.', '2008-01-09 17:48:14.000000', NULL, 1),
(4378722, 629946, 62009, '<td valign="top">Nice even spread between the bodies.  I could definitely see this hanging in a skate shop.</td>', 'Nice even spread between the bodies.  I could definitely see this hanging in a skate shop.', '2008-01-09 17:49:23.000000', NULL, 1),
(4378727, 629942, 62009, '<td valign="top">Nice DOF on this.  I love the expressions.</td>', 'Nice DOF on this.  I love the expressions.', '2008-01-09 17:50:48.000000', NULL, 1),
(4378730, 629863, 62009, '<td valign="top">This is wonderful.  Beautiful bird and landing.</td>', 'This is wonderful.  Beautiful bird and landing.', '2008-01-09 17:51:27.000000', NULL, 1),
(4378737, 629883, 62009, '<td valign="top">I can so see myself doing this.  My only nitpick is the one of you all the way back can be seen through, as if it was part of a long-exposure.</td>', 'I can so see myself doing this.  My only nitpick is the one of you all the way back can be seen through, as if it was part of a long-exposure.', '2008-01-09 17:53:04.000000', NULL, 1),
(4378740, 629087, 62009, '<td valign="top">Very interesting.  Nice and sharp.  Looks like the bowl is either scratched or oversharpened as to bring out artifacts.</td>', 'Very interesting.  Nice and sharp.  Looks like the bowl is either scratched or oversharpened as to bring out artifacts.', '2008-01-09 17:53:56.000000', NULL, 1),
(4378742, 628021, 62009, '<td valign="top">This is absolutely gorgeous.  I had to look a couple of times to see the boat floating, it just didn''t pop out to me.</td>', 'This is absolutely gorgeous.  I had to look a couple of times to see the boat floating, it just didn''t pop out to me.', '2008-01-09 17:55:02.000000', NULL, 1),
(4378744, 628806, 62009, '<td valign="top">Excellent contre jour.</td>', 'Excellent contre jour.', '2008-01-09 17:55:40.000000', NULL, 1),
(4378745, 628788, 23433, '<td valign="top">Great picture, but I am not sure how it fits into the Time Lapse Challenge.</td>', 'Great picture, but I am not sure how it fits into the Time Lapse Challenge.', '2008-01-09 17:55:50.000000', NULL, 1),
(4378746, 629494, 62009, '<td valign="top">Interesting wilting flower.  I''m not too keen on the "see-through" petals.</td>', 'Interesting wilting flower.  I''m not too keen on the "see-through" petals.', '2008-01-09 17:56:15.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4378749, 629583, 62009, '<td valign="top">The sky is absolutely gorgeous in this shot.  I had to double-take to see that the ball was actually hit off the tee...WOW!!!</td>', 'The sky is absolutely gorgeous in this shot.  I had to double-take to see that the ball was actually hit off the tee...WOW!!!', '2008-01-09 17:57:16.000000', NULL, 1),
(4378750, 629757, 62009, '<td valign="top">Great POV and BW conversion.</td>', 'Great POV and BW conversion.', '2008-01-09 17:59:01.000000', NULL, 1),
(4378755, 629756, 62009, '<td valign="top">Different take on this.  While most of the shots show actual movement, you show the progress from day to night.  I love it.</td>', 'Different take on this.  While most of the shots show actual movement, you show the progress from day to night.  I love it.', '2008-01-09 18:00:26.000000', NULL, 1),
(4378760, 629658, 62009, '<td valign="top">I love star shots.  I would have tried to adjust the curves to get the sky darker, rather than using the long exposure to lighten the sky.</td>', 'I love star shots.  I would have tried to adjust the curves to get the sky darker, rather than using the long exposure to lighten the sky.', '2008-01-09 18:02:09.000000', NULL, 1),
