(4389192, 628021, 70298, '<td valign="top">Really love this shot, it is so calm and peaceful. Lovely colour and effective frame. 10 :)</td>', 'Really love this shot, it is so calm and peaceful. Lovely colour and effective frame. 10 :)', '2008-01-13 14:37:52.000000', NULL, 1),
(4389197, 629885, 70298, '<td valign="top">Great photo. Love the blur of the seagulls wings as it flys away and the calm colours. amazing. 10 :)</td>', 'Great photo. Love the blur of the seagulls wings as it flys away and the calm colours. amazing. 10 :)', '2008-01-13 14:39:53.000000', NULL, 1),
(4389388, 629961, 67258, '<td valign="top">Ultra cool!  I have returned to this photo time and time again over the couse of this last week, intrigued by it.  Certainly the most creative photo in the challenge, and also or me the most visually appealing.  10.</td>', 'Ultra cool!  I have returned to this photo time and time again over the couse of this last week, intrigued by it.  Certainly the most creative photo in the challenge, and also or me the most visually appealing.  10.', '2008-01-13 16:28:03.000000', NULL, 1),
(4389399, 629448, 67258, '<td valign="top">Hmmm, I am in a real quandry - to me the photo really illustrates the challenge <u><b>Title</b></u> well, and I like the simplicity with which it achieves this, BUT, I don''t see how it fits with the challenge <u>description</u> (<i>use multiple captures of a continuous, single scene to demonstrate time lapse photography</i>) at all.</td>', 'Hmmm, I am in a real quandry - to me the photo really illustrates the challenge Title well, and I like the simplicity with which it achieves this, BUT, I don''t see how it fits with the challenge description (use multiple captures of a continuous, single scene to demonstrate time lapse photography) at all.', '2008-01-13 16:30:49.000000', NULL, 1),
(4389409, 629706, 88642, '<td valign="top">grand idea! i really love the result :D</td>', 'grand idea! i really love the result :D', '2008-01-13 16:36:29.000000', NULL, 1),
(4389447, 629952, 61961, '<td valign="top">Whoa, it took me awhile to get this one.  I thought at first you had just done a long exposure.  Very clever, nicely done.</td>', 'Whoa, it took me awhile to get this one.  I thought at first you had just done a long exposure.  Very clever, nicely done.', '2008-01-13 17:15:15.000000', NULL, 1),
(4389448, 629226, 10818, '<td valign="top">Ha, thats really cute...nice shot.</td>', 'Ha, thats really cute...nice shot.', '2008-01-13 17:15:20.000000', NULL, 1),
(4389452, 629287, 10818, '<td valign="top">Such concentration, great sequence.</td>', 'Such concentration, great sequence.', '2008-01-13 17:17:30.000000', NULL, 1),
(4389456, 629425, 10818, '<td valign="top">Adorable clown fish, super marine shot.</td>', 'Adorable clown fish, super marine shot.', '2008-01-13 17:19:57.000000', NULL, 1),
(4389457, 629557, 10818, '<td valign="top">Quite an impressive jump, great shot.</td>', 'Quite an impressive jump, great shot.', '2008-01-13 17:20:09.000000', NULL, 1),
(4389460, 629850, 10818, '<td valign="top">Fantastic portrait, hands on the frets are really well done.</td>', 'Fantastic portrait, hands on the frets are really well done.', '2008-01-13 17:22:51.000000', NULL, 1),
(4389461, 629757, 10818, '<td valign="top">Amazing shot, B@W works great.</td>', 'Amazing shot, B@W works great.', '2008-01-13 17:24:06.000000', NULL, 1),
(4389465, 628555, 10818, '<td valign="top">The bird really makes the shot, interesting background.</td>', 'The bird really makes the shot, interesting background.', '2008-01-13 17:25:20.000000', NULL, 1),
