(4389472, 629863, 10818, '<td valign="top">Pelicans are gorgeous birds, great capture.</td>', 'Pelicans are gorgeous birds, great capture.', '2008-01-13 17:28:02.000000', NULL, 1),
(4389534, 629885, 44754, '<td valign="top">very cool image</td>', 'very cool image', '2008-01-13 18:14:36.000000', NULL, 1),
