(4389546, 629739, 44754, '<td valign="top">unfortunately, to me just seems like 6 different bucks running together. like that would ever happen though.<br/>Also, they kinda blend in with the brush.</td>', 'unfortunately, to me just seems like 6 different bucks running together. like that would ever happen though.Also, they kinda blend in with the brush.', '2008-01-13 18:19:44.000000', NULL, 1),
(4389547, 629557, 44754, '<td valign="top">would maybe "burn" the rider a bit.</td>', 'would maybe "burn" the rider a bit.', '2008-01-13 18:20:26.000000', NULL, 1),
