INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4389567, 629577, 44754, '<td valign="top">great shot but needs more contrast to give it more punch.</td>', 'great shot but needs more contrast to give it more punch.', '2008-01-13 18:27:18.000000', NULL, 1),
(4389569, 629600, 44754, '<td valign="top">too many shots. don''t think this works well in B+W</td>', 'too many shots. don''t think this works well in B+W', '2008-01-13 18:28:09.000000', NULL, 1),
(4389572, 628727, 44754, '<td valign="top">any way to lose some noise?</td>', 'any way to lose some noise?', '2008-01-13 18:28:49.000000', NULL, 1),
(4389573, 629705, 44754, '<td valign="top">ah, to me a kid again. very nice shot(s)</td>', 'ah, to me a kid again. very nice shot(s)', '2008-01-13 18:29:24.000000', NULL, 1),
(4389576, 629339, 44754, '<td valign="top">wow a 3 headed lion. that looks freaky.</td>', 'wow a 3 headed lion. that looks freaky.', '2008-01-13 18:30:26.000000', NULL, 1),
(4389577, 629754, 44754, '<td valign="top">at least he''s having fun.</td>', 'at least he''s having fun.', '2008-01-13 18:31:35.000000', NULL, 1),
(4389579, 627641, 44754, '<td valign="top">looks oversated to me.</td>', 'looks oversated to me.', '2008-01-13 18:33:02.000000', NULL, 1),
(4389581, 628895, 44754, '<td valign="top">really don''t see the gun very well. maybe more lighting on the gun</td>', 'really don''t see the gun very well. maybe more lighting on the gun', '2008-01-13 18:33:44.000000', NULL, 1),
(4389582, 627954, 44754, '<td valign="top">would have either used one more shot at the end or lose the first one.</td>', 'would have either used one more shot at the end or lose the first one.', '2008-01-13 18:34:46.000000', NULL, 1),
(4389583, 629942, 44754, '<td valign="top">Man, she pissed off.</td>', 'Man, she pissed off.', '2008-01-13 18:35:21.000000', NULL, 1),
(4389587, 629945, 44754, '<td valign="top">guessing the first or last 7 were taken and then she stepped in for the final or first shot?</td>', 'guessing the first or last 7 were taken and then she stepped in for the final or first shot?', '2008-01-13 18:37:09.000000', NULL, 1),
(4389588, 629701, 44754, '<td valign="top">look out, its the ghost sail.</td>', 'look out, its the ghost sail.', '2008-01-13 18:37:38.000000', NULL, 1),
(4389593, 629441, 44754, '<td valign="top">wow, two sets of skiing twins. don''t see that very often.</td>', 'wow, two sets of skiing twins. don''t see that very often.', '2008-01-13 18:39:24.000000', NULL, 1),
(4389594, 629687, 44754, '<td valign="top">that''s just plane goofy</td>', 'that''s just plane goofy', '2008-01-13 18:39:56.000000', NULL, 1),
(4389596, 628989, 44754, '<td valign="top">beautiful white snow. it''s weird, the skier seems like he was PS''d in. almost like the weather guy with the "green" screen.</td>', 'beautiful white snow. it''s weird, the skier seems like he was PS''d in. almost like the weather guy with the "green" screen.', '2008-01-13 18:41:38.000000', NULL, 1),
(4389764, 629946, 50695, '<td valign="top">Manic: I don''t know, he looks bored.<br/> <br/>muckpond: that''s because he''s so good at it. It''s confidence!<br/> <br/>Manic: but boredom isn''t natural.<br/> <br/>muckpond: my dog gets bored all the time.<br/> <br/>Manic: exactly, a dog is a domesticated animal, not natural.<br/> <br/>muckpond: then let''s go back and DQ all the dog shots.<br/> <br/>scalvert: DQ! DQ! DQ! DQ!<br/> <br/>Manic: plus he''s in the city. The city''s not natural. Where are the trees?<br/> <br/>muckpond: They''re behind the fence.<br/> <br/>Manic: well that''s depressing.<br/> <br/>muckpond: naturally.</td>', 'Manic: I don''t know, he looks bored. muckpond: that''s because he''s so good at it. It''s confidence! Manic: but boredom isn''t natural. muckpond: my dog gets bored all the time. Manic: exactly, a dog is a domesticated animal, not natural. muckpond: then let''s go back and DQ all the dog shots. scalvert: DQ! DQ! DQ! DQ! Manic: plus he''s in the city. The city''s not natural. Where are the trees? muckpond: They''re behind the fence. Manic: well that''s depressing. muckpond: naturally.', '2008-01-13 20:41:55.000000', NULL, 1),
(4389773, 629942, 50695, '<td valign="top">muckpond: cool! those women are all going to crash into each other.<br/> <br/>Manic: this is time lapse.<br/> <br/>muckpond: oh. then why don''t I see the crash?<br/> <br/>Manic: it''s one woman. this is her progression down the hill.<br/> <br/>scalvert: a natural progression caused by gravity. she''s not even steering.<br/> <br/>muckpond: one woman?<br/> <br/>Manic: yeah, didn''t you notice how they all look alike? <br/> <br/>muckpond: cool! crashing quadruplets!</td>', 'muckpond: cool! those women are all going to crash into each other. Manic: this is time lapse. muckpond: oh. then why don''t I see the crash? Manic: it''s one woman. this is her progression down the hill. scalvert: a natural progression caused by gravity. she''s not even steering. muckpond: one woman? Manic: yeah, didn''t you notice how they all look alike?  muckpond: cool! crashing quadruplets!', '2008-01-13 20:44:05.000000', NULL, 1),
(4389785, 629562, 50695, '<td valign="top">scalvert: there''s nothing natural about teenagers.<br/> <br/>frisca: that''s more of a strut than a stroll. I think a strut is less natural than a stroll.<br/> <br/>L2: only humans stroll. I saw that on PBS.<br/> <br/>ursula: that color ain''t natural. It''s pretty, though!<br/> <br/>sher: natural beauty. let''s go with it.</td>', 'scalvert: there''s nothing natural about teenagers. frisca: that''s more of a strut than a stroll. I think a strut is less natural than a stroll. L2: only humans stroll. I saw that on PBS. ursula: that color ain''t natural. It''s pretty, though! sher: natural beauty. let''s go with it.', '2008-01-13 20:49:27.000000', NULL, 1),
(4389787, 629406, 50695, '<td valign="top">scalvert: this is definitely natural. he even has Newton in the title. I feel so strange...<br/> <br/>sher: what is it?<br/> <br/>scalvert: I... I feel this strange excitement...<br/> <br/>sher: okay... I''ve heard enough...<br/> <br/>GeneralE: the man really loves physics.</td>', 'scalvert: this is definitely natural. he even has Newton in the title. I feel so strange... sher: what is it? scalvert: I... I feel this strange excitement... sher: okay... I''ve heard enough... GeneralE: the man really loves physics.', '2008-01-13 20:50:47.000000', NULL, 1),
(4389789, 629938, 50695, '<td valign="top">GeneralE: okay now tell me what single motion this is.<br/> <br/>sher: the single motion of a self-embrace.<br/> <br/>muckpond: yeah, I do this all the time. One motion.</td>', 'GeneralE: okay now tell me what single motion this is. sher: the single motion of a self-embrace. muckpond: yeah, I do this all the time. One motion.', '2008-01-13 20:51:56.000000', NULL, 1),
(4389798, 629694, 50695, '<td valign="top">GeneralE: that''s at least two motions.<br/> <br/>muckpond: no, man, it''s one double-motion. It''s like when Dorothy Hamill says someone just nailed a triple toe loop. It''s not three toe loops.<br/> <br/>GeneralE: well, Dorothy Hamill is never wrong.<br/> <br/>muckpond: Amen.</td>', 'GeneralE: that''s at least two motions. muckpond: no, man, it''s one double-motion. It''s like when Dorothy Hamill says someone just nailed a triple toe loop. It''s not three toe loops. GeneralE: well, Dorothy Hamill is never wrong. muckpond: Amen.', '2008-01-13 20:56:23.000000', NULL, 1),
(4389802, 629425, 50695, '<td valign="top">Manic: okay, those fish all look alike. how are we supposed to know this is time lapse?<br/> <br/>ursula: they all look alike? Are you prejudiced?<br/> <br/>Manic: yes, I have fish prejudice. That''s why I eat them.<br/> <br/>ursula: EWWW!</td>', 'Manic: okay, those fish all look alike. how are we supposed to know this is time lapse? ursula: they all look alike? Are you prejudiced? Manic: yes, I have fish prejudice. That''s why I eat them. ursula: EWWW!', '2008-01-13 20:57:50.000000', NULL, 1),
(4389806, 629630, 50695, '<td valign="top">frisca: Is vignetting natural? <br/> <br/>Manic: are old cars natural?<br/> <br/>muckpond: whoa, that car''s older than I am!<br/> <br/>GeneralE: by a mile.</td>', 'frisca: Is vignetting natural?  Manic: are old cars natural? muckpond: whoa, that car''s older than I am! GeneralE: by a mile.', '2008-01-13 20:59:16.000000', NULL, 1),
(4389810, 629020, 50695, '<td valign="top">sher: I think that''s the longest walk of the challenge.<br/> <br/>GeneralE: I admire persistence.</td>', 'sher: I think that''s the longest walk of the challenge. GeneralE: I admire persistence.', '2008-01-13 21:00:04.000000', NULL, 1),
(4389819, 629686, 50695, '<td valign="top">frisca: grass and water is natural.<br/> <br/>muckpond: kids jumping over stuff is natural!<br/> <br/>scalvert: alright, you can have this one. But I''m DQing the rest!</td>', 'frisca: grass and water is natural. muckpond: kids jumping over stuff is natural! scalvert: alright, you can have this one. But I''m DQing the rest!', '2008-01-13 21:02:33.000000', NULL, 1),
(4389822, 627954, 50695, '<td valign="top">Manic: that''s tough to do. I keep falling off those things.<br/> <br/>sher: the title''s a little depressing.<br/> <br/>ursula: no it''s not! I talk to myself all the time! It''s fun!<br/> <br/>scalvert: guys, I''ve noticed we tend to get a little off-topic lately. Is this natural or not?<br/> <br/>muckpond: Kid. Playground. Playing. It''s natural!</td>', 'Manic: that''s tough to do. I keep falling off those things. sher: the title''s a little depressing. ursula: no it''s not! I talk to myself all the time! It''s fun! scalvert: guys, I''ve noticed we tend to get a little off-topic lately. Is this natural or not? muckpond: Kid. Playground. Playing. It''s natural!', '2008-01-13 21:04:31.000000', NULL, 1),
(4389827, 629335, 50695, '<td valign="top">GeneralE: Interesting point. Is movement more natural when it''s candid? Since the will of the photographer is not involved, does that mean the motion is natural, part of the uncontrolled Universe that surrounds us all?<br/> <br/>karmat: Is there anything over which we truly have control? All we can do is disturb karma, but that is always restored by the karmic wheel.<br/> <br/>scalvert: superstitious nonsense! what principle of physics is being demonstrated here?<br/> <br/>muckpond: um... it snows in the winter? people''s hair gets white when they get old?</td>', 'GeneralE: Interesting point. Is movement more natural when it''s candid? Since the will of the photographer is not involved, does that mean the motion is natural, part of the uncontrolled Universe that surrounds us all? karmat: Is there anything over which we truly have control? All we can do is disturb karma, but that is always restored by the karmic wheel. scalvert: superstitious nonsense! what principle of physics is being demonstrated here? muckpond: um... it snows in the winter? people''s hair gets white when they get old?', '2008-01-13 21:07:18.000000', NULL, 1),
(4389833, 628714, 50695, '<td valign="top">GeneralE: a single quack. that''s natural.<br/> <br/>frisca: but the title has two quacks.<br/> <br/>sher: I like that we can see all the reflections, too.<br/> <br/>frisca: is a quack a motion? I thought it was a sound?<br/> <br/>GeneralE: sound is the motion of soundwaves through the air.<br/> <br/>frisca: are you hearing things again?</td>', 'GeneralE: a single quack. that''s natural. frisca: but the title has two quacks. sher: I like that we can see all the reflections, too. frisca: is a quack a motion? I thought it was a sound? GeneralE: sound is the motion of soundwaves through the air. frisca: are you hearing things again?', '2008-01-13 21:10:30.000000', NULL, 1),
(4389840, 629284, 50695, '<td valign="top">scalvert: once again, I have to ask if the voluntary decisions of an athlete...<br/> <br/>muckpond: hold up there! from now on, all snowboarding is natural! I decree it! this shot is so cool!</td>', 'scalvert: once again, I have to ask if the voluntary decisions of an athlete... muckpond: hold up there! from now on, all snowboarding is natural! I decree it! this shot is so cool!', '2008-01-13 21:12:18.000000', NULL, 1),
(4389845, 629701, 50695, '<td valign="top">scalvert: okay, that''s physics. the action of wind on a chute.<br/> <br/>ursula: scalvert! he likes it! but he hates everything! <br/> <br/>scalvert: cute, Marie. real cute...</td>', 'scalvert: okay, that''s physics. the action of wind on a chute. ursula: scalvert! he likes it! but he hates everything!  scalvert: cute, Marie. real cute...', '2008-01-13 21:13:50.000000', NULL, 1),
(4389851, 629494, 50695, '<td valign="top">sher: wow. somebody''s patient.<br/> <br/>scalvert: I''ve got to hand it to this photographer. It meets the challenge dead on and exactly conforms to our secret ideas about what "time lapse photography" means.<br/> <br/>sher: hmmm... this isn''t your photograph, is it?<br/> <br/>scalvert: no comment.</td>', 'sher: wow. somebody''s patient. scalvert: I''ve got to hand it to this photographer. It meets the challenge dead on and exactly conforms to our secret ideas about what "time lapse photography" means. sher: hmmm... this isn''t your photograph, is it? scalvert: no comment.', '2008-01-13 21:15:39.000000', NULL, 1),
(4389859, 629600, 50695, '<td valign="top">L2: okay, birds are natural.<br/> <br/>frisca: even sparrows? do you know they eat garbage?<br/> <br/>L2: yuck! they''re still natural.<br/> <br/>muckpond: yeah! Law of the Jungle! one man''s garbage is another man''s marmalade. I read it in Jungle Books.</td>', 'L2: okay, birds are natural. frisca: even sparrows? do you know they eat garbage? L2: yuck! they''re still natural. muckpond: yeah! Law of the Jungle! one man''s garbage is another man''s marmalade. I read it in Jungle Books.', '2008-01-13 21:17:50.000000', NULL, 1),
(4389868, 628985, 50695, '<td valign="top">frisca: are motorcycles natural?<br/> <br/>Manic: it''s not even a Harley.<br/> <br/>scalvert: those colors aren''t natural.<br/> <br/>muckpond: I like how his motion extends all the way down the road and out of sight.<br/> <br/>scalvert: this is not an aesthetic discussion.<br/> <br/>muckpond: but for some the distinction between what is natural and what is unnatural is based on aesthetics.<br/> <br/>scalvert: whoa, dude.</td>', 'frisca: are motorcycles natural? Manic: it''s not even a Harley. scalvert: those colors aren''t natural. muckpond: I like how his motion extends all the way down the road and out of sight. scalvert: this is not an aesthetic discussion. muckpond: but for some the distinction between what is natural and what is unnatural is based on aesthetics. scalvert: whoa, dude.', '2008-01-13 21:21:18.000000', NULL, 1),
(4389875, 628021, 50695, '<td valign="top">scalvert: totally natural. a floating object following the current.<br/> <br/>frisca: but a newspaper''s not natural.<br/> <br/>scalvert: it is when it''s folded into a boat.<br/> <br/>ursula: but it''s still black and white and read all over, and that''s not natural.<br/> <br/>muckpond: zebra with a sunburn! natural!</td>', 'scalvert: totally natural. a floating object following the current. frisca: but a newspaper''s not natural. scalvert: it is when it''s folded into a boat. ursula: but it''s still black and white and read all over, and that''s not natural. muckpond: zebra with a sunburn! natural!', '2008-01-13 21:23:27.000000', NULL, 1),
(4389878, 629577, 50695, '<td valign="top">muckpond: okay! all surfing is natural! no more discussion!</td>', 'muckpond: okay! all surfing is natural! no more discussion!', '2008-01-13 21:24:45.000000', NULL, 1),
(4389880, 629223, 50695, '<td valign="top">scalvert: ah, the pendulum action of a swing.  perfectly natural!<br/> <br/>GeneralE: ah, the joys of childhood. perfectly natural!</td>', 'scalvert: ah, the pendulum action of a swing.  perfectly natural! GeneralE: ah, the joys of childhood. perfectly natural!', '2008-01-13 21:25:47.000000', NULL, 1),
(4389886, 629961, 50695, '<td valign="top">I don''t know how the heck you did this but this is so fricking cool.<br/> <br/>Posthumous Blue Ribbon. <img alt="'' . substr(''//blackyak.com/dpc/bluepost.jpg'', strrpos(''//blackyak.com/dpc/bluepost.jpg'', ''/'') + 1) . ''" border="0" src="//blackyak.com/dpc/bluepost.jpg"/></td>', 'I don''t know how the heck you did this but this is so fricking cool. Posthumous Blue Ribbon. ', '2008-01-13 21:27:03.000000', NULL, 1),
(4389888, 628555, 50695, '<td valign="top">frisca: the bird''s natural, but what about the bicycle?<br/> <br/>scalvert: a bicycle is physics in action. so is a bird.<br/> <br/>GeneralE: I''ll tell you what''s not natural. Three bikers, only one reflection.<br/> <br/>muckpond: yeah, but he got the shadows! and the bird and the bike together! is that cool or what??</td>', 'frisca: the bird''s natural, but what about the bicycle? scalvert: a bicycle is physics in action. so is a bird. GeneralE: I''ll tell you what''s not natural. Three bikers, only one reflection. muckpond: yeah, but he got the shadows! and the bird and the bike together! is that cool or what??', '2008-01-13 21:27:16.000000', NULL, 1),
(4389889, 629739, 50695, '<td valign="top">ursula: nice colors! this is so pretty!<br/> <br/>frisca: deer... definitely natural.<br/> <br/>scalvert: shucks, I love it when you call me deer.</td>', 'ursula: nice colors! this is so pretty! frisca: deer... definitely natural. scalvert: shucks, I love it when you call me deer.', '2008-01-13 21:27:19.000000', NULL, 1),
(4389890, 629908, 50695, '<td valign="top">frisca: notice how the boys almost intermingle. this really represents time lapse according to those secret criteria that we''re not telling anyone.<br/> <br/>ursula: indeed. and it''s pretty, too!</td>', 'frisca: notice how the boys almost intermingle. this really represents time lapse according to those secret criteria that we''re not telling anyone. ursula: indeed. and it''s pretty, too!', '2008-01-13 21:27:22.000000', NULL, 1),
(4389891, 629705, 50695, '<td valign="top">GeneralE: two people, does that mean two motions?<br/> <br/>muckpond: no, it''s synchronized! like synchronized swimming!<br/> <br/>sher: except it''s more fun.</td>', 'GeneralE: two people, does that mean two motions? muckpond: no, it''s synchronized! like synchronized swimming! sher: except it''s more fun.', '2008-01-13 21:27:26.000000', NULL, 1),
(4389892, 628806, 50695, '<td valign="top">ursula: wow! that''s beautiful!<br/> <br/>muckpond: kid running on the beach. totally natural!</td>', 'ursula: wow! that''s beautiful! muckpond: kid running on the beach. totally natural!', '2008-01-13 21:27:30.000000', NULL, 1),
(4389893, 629952, 50695, '<td valign="top">GeneralE: this doesn''t really convey motion, per se...<br/> <br/>muckpond: shut up! this is so cool!</td>', 'GeneralE: this doesn''t really convey motion, per se... muckpond: shut up! this is so cool!', '2008-01-13 21:27:43.000000', NULL, 1),
(4389895, 629883, 50695, '<td valign="top">frisca: he''s too old to be on the swings. that''s not natural.<br/> <br/>muckpond: dude! nice tuck and roll!<br/> <br/>scalvert: look at that arabesque as he leaves the swing. that''s not physics.<br/> <br/>ursula: aww, but it''s so pretty.</td>', 'frisca: he''s too old to be on the swings. that''s not natural. muckpond: dude! nice tuck and roll! scalvert: look at that arabesque as he leaves the swing. that''s not physics. ursula: aww, but it''s so pretty.', '2008-01-13 21:28:12.000000', NULL, 1),
(4389896, 629851, 50695, '<td valign="top">GeneralE: ah, this is beautiful. all hints of volition and intelligence are outside of frame. this is pure motion.<br/> <br/>scalvert: pure Newtonian physics.<br/> <br/>ursula: what with the metal basket?<br/> <br/>GeneralE: it''s a tough world, ursula.</td>', 'GeneralE: ah, this is beautiful. all hints of volition and intelligence are outside of frame. this is pure motion. scalvert: pure Newtonian physics. ursula: what with the metal basket? GeneralE: it''s a tough world, ursula.', '2008-01-13 21:28:18.000000', NULL, 1),
(4389897, 629087, 50695, '<td valign="top">GeneralE: that''s definitely not a single motion.<br/> <br/>karmat: it represents the single motion of the Gaiasphere, the delicate yet supreme circle of life.<br/> <br/>GeneralE: we need to deal with reality here, not symbols.<br/> <br/>karmat: do not underestimate the power of symbols.<br/> <br/>muckpond: (enlightenbulb goes off) Whoa! I see it now! It''s about global warming!<br/> <br/>ursula: well, that''s certainly not natural.</td>', 'GeneralE: that''s definitely not a single motion. karmat: it represents the single motion of the Gaiasphere, the delicate yet supreme circle of life. GeneralE: we need to deal with reality here, not symbols. karmat: do not underestimate the power of symbols. muckpond: (enlightenbulb goes off) Whoa! I see it now! It''s about global warming! ursula: well, that''s certainly not natural.', '2008-01-13 21:28:23.000000', NULL, 1),
(4389898, 627641, 50695, '<td valign="top">scalvert: human motion reeks of volition. not natural.<br/> <br/>ursula: ah, but look at the hood flying off her head. natural result of air friction and momentum.<br/> <br/>muckpond: it''s cold! she''s running to her car! totally natural!</td>', 'scalvert: human motion reeks of volition. not natural. ursula: ah, but look at the hood flying off her head. natural result of air friction and momentum. muckpond: it''s cold! she''s running to her car! totally natural!', '2008-01-13 21:28:29.000000', NULL, 1),
(4389899, 629885, 50695, '<td valign="top">muckpond: awesome!<br/> <br/>frisca: birds are natural agents.<br/> <br/>scalvert: but the photographer left something on that bench. It''s staged.<br/> <br/>GeneralE: and note there are TWO motions: the motion toward the prize and the escape with the loot. Not natural.<br/> <br/>muckpond: grabbing a bite to eat. totall natural!</td>', 'muckpond: awesome! frisca: birds are natural agents. scalvert: but the photographer left something on that bench. It''s staged. GeneralE: and note there are TWO motions: the motion toward the prize and the escape with the loot. Not natural. muckpond: grabbing a bite to eat. totall natural!', '2008-01-13 21:28:36.000000', NULL, 1),
(4389903, 629757, 50695, '<td valign="top">scalvert: ah, the classic physics of aerodynamics. I vote natural.<br/> <br/>ursula: this isn''t nature. It''s High Tech!<br/> <br/>muckpond: it''s not high tech, it''s hotpasta.<br/> <br/>scalvert: how do you know?<br/> <br/>muckpond: I smell ribbon.<br/> <br/>scalvert: grrrrr</td>', 'scalvert: ah, the classic physics of aerodynamics. I vote natural. ursula: this isn''t nature. It''s High Tech! muckpond: it''s not high tech, it''s hotpasta. scalvert: how do you know? muckpond: I smell ribbon. scalvert: grrrrr', '2008-01-13 21:29:25.000000', NULL, 1),
